/// <summary>
/// MPJ_22974_PBMSProductMDRItemStatusAndPackChange
/// Eventhandler class for InventOnhandItem form
/// </summary>
class METInventOnhandItemFormEventHandler
{     
}

Method.Source:
    /// <summary>
    /// MPJ_22974_PBMSProductMDRItemStatusAndPackChange
    /// To control visibility of CW and Invent qty when sales quantity modified
    /// </summary>
    /// <param name="sender">from control</param>
    /// <param name="e">args</param>
    [FormControlEventHandler(formControlStr(InventOnhandItem, METPdsCWInventQuantityDisplay), FormControlEventType::Modified),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void METPdsCWInventQuantityDisplay_Modified(FormControl sender, FormControlEventArgs e)
    {
        InventSum inventSum = sender.formRun().dataSource(formDataSourceStr(InventOnhandItem,InventSum)).cursor();
        InventDim inventDim = sender.formRun().dataSource(formDataSourceStr(InventOnhandItem,inventDim)).cursor();
        FormComboBoxControl  METPdsCWInventQuantityDisplay  = sender.formRun().design(0).controlName('METPdsCWInventQuantityDisplay');
        FormComboBoxControl  cWInventQuantityDisplay        = sender.formRun().design(0).controlName('CWInventQuantityDisplay');
        FormControl          salesQtyGroup                  = sender.formRun().design(0).controlName('SalesQtyGroup');
        METPdsCWInventQuantityDisplay selectionNew          = METPdsCWInventQuantityDisplay.selection();
        boolean                       salesQty              = selectionNew == METPdsCWInventQuantityDisplay::Sales;

        if (!salesQty)
        {
            if(METPdsCWInventQuantityDisplay.valueStr() == enum2Str(METPdsCWInventQuantityDisplay::Inventory))
            {                
                cWInventQuantityDisplay.selection(PdsCWInventQuantityDisplay::Inventory);

            }
            if(METPdsCWInventQuantityDisplay.valueStr() == enum2Str(METPdsCWInventQuantityDisplay::CatchWeight))
            {                              
                cWInventQuantityDisplay.selection(PdsCWInventQuantityDisplay::CatchWeight);
            }
           
            cWInventQuantityDisplay.modified();
            
            salesQtyGroup.visible(salesQty);
        }
        else
        {
            PmfFormCtrl_InventOnHandItem pmfFormCtrl_InventOnHandIte = PmfFormCtrl_InventOnHandItem::newFromForm(sender.formRun());
            
            pmfFormCtrl_InventOnHandIte.setDatasources(inventSum, inventDim);
            pmfFormCtrl_InventOnHandIte.initPost();

            salesQtyGroup.visible(salesQty);
        }
    }
